package com.rohit.inventory.controller;
import com.rohit.inventory.dto.request.*; import com.rohit.inventory.dto.response.*; import com.rohit.inventory.entity.UserStatus; import com.rohit.inventory.service.UserService; import jakarta.validation.Valid; import java.util.UUID; import org.springframework.data.domain.*; import org.springframework.data.web.PageableDefault; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.security.core.userdetails.UserDetails; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/users") public class UserController { private final UserService service; public UserController(UserService service){this.service=service;} @GetMapping @PreAuthorize("hasAuthority('USER_READ')") public ApiResponse<Page<UserResponse>> list(@RequestParam(required=false) String search,@RequestParam(required=false) UserStatus status,@RequestParam(required=false) String role,@PageableDefault(size=20,sort="createdAt",direction=Sort.Direction.DESC) Pageable pageable){return ApiResponse.success("Users retrieved successfully",service.list(search,status,role,pageable));} @GetMapping("/{id}") @PreAuthorize("hasAuthority('USER_READ')") public ApiResponse<UserResponse> get(@PathVariable UUID id){return ApiResponse.success("User retrieved successfully",service.get(id));} @PostMapping @PreAuthorize("hasAuthority('USER_CREATE')") public ApiResponse<UserResponse> create(@Valid @RequestBody CreateUserRequest r,@AuthenticationPrincipal UserDetails user){return ApiResponse.success("User created successfully",service.create(r,service.idForEmail(user.getUsername())));} @PutMapping("/{id}") @PreAuthorize("hasAuthority('USER_UPDATE')") public ApiResponse<UserResponse> update(@PathVariable UUID id,@Valid @RequestBody UpdateUserRequest r,@AuthenticationPrincipal UserDetails user){return ApiResponse.success("User updated successfully",service.update(id,r,service.idForEmail(user.getUsername())));} @PatchMapping("/{id}/status") @PreAuthorize("hasAuthority('USER_DEACTIVATE')") public ApiResponse<UserResponse> status(@PathVariable UUID id,@Valid @RequestBody UpdateUserStatusRequest r,@AuthenticationPrincipal UserDetails user){return ApiResponse.success("User status updated successfully",service.status(id,r,service.idForEmail(user.getUsername())));} @DeleteMapping("/{id}") @PreAuthorize("hasAuthority('USER_DEACTIVATE')") public ApiResponse<UserResponse> deactivate(@PathVariable UUID id,@AuthenticationPrincipal UserDetails user){return ApiResponse.success("User deactivated successfully",service.status(id,new UpdateUserStatusRequest(UserStatus.INACTIVE),service.idForEmail(user.getUsername())));} @PatchMapping("/{id}/roles") @PreAuthorize("hasAuthority('ROLE_ASSIGN')") public ApiResponse<UserResponse> roles(@PathVariable UUID id,@Valid @RequestBody AssignRolesRequest r,@AuthenticationPrincipal UserDetails user){return ApiResponse.success("User roles updated successfully",service.roles(id,r,service.idForEmail(user.getUsername())));} }
